document.addEventListener("DOMContentLoaded",function(){const toggler=document.getElementById("theme-toggler");const HTML=document.getElementsByTagName("html")[0];const stored=localStorage.getItem("theme")||"light";HTML.dataset.theme=stored;if(toggler){toggler.checked=stored==="dark";toggler.addEventListener("click",()=>{const newTheme=toggler.checked?"dark":"light";HTML.dataset.theme=newTheme;localStorage.setItem("theme",newTheme)})}});
